<?php declare(strict_types=1);require __DIR__.'/inc/db.php';require __DIR__.'/inc/auth.php';require_customer();$config=require __DIR__.'/inc/xendit.php';$secret=(string)$config['secret_key'];if($secret==='')exit('Xendit is not configured.');$id=(int)($_GET['order_id']??0);$q=$pdo->prepare("SELECT o.*,h.id header_id,h.user_id FROM orders o JOIN order_headers h ON h.normal_order_id=o.id WHERE o.id=? AND h.user_id=?");$q->execute([$id,user_id()]);$o=$q->fetch();if(!$o)exit('Order not found.');if($o['payment_status']==='paid')redirect('order_details.php?id='.$o['header_id']);if($o['payment']!=='gcash')exit('This is not a GCash order.');if(!empty($o['payment_reference']))redirect($o['payment_reference']);$amount=(float)$o['total'];if($amount<1)exit('Payment amount must be at least ₱1.');$base=rtrim((string)env_value('APP_URL','http://localhost/AI-CAKE'),'/');$payload=['external_id'=>$o['order_number'],'amount'=>$amount,'currency'=>'PHP','description'=>'Cake order '.$o['order_number'],'payment_methods'=>['GCASH'],'success_redirect_url'=>$base.'/order_details.php?id='.$o['header_id'],'failure_redirect_url'=>$base.'/order_details.php?id='.$o['header_id']];$ch=curl_init('https://api.xendit.co/v2/invoices');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($payload),CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Basic '.base64_encode($secret.':')],CURLOPT_TIMEOUT=>30,CURLOPT_SSL_VERIFYPEER=>true]);$raw=curl_exec($ch);$http=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$r=json_decode((string)$raw,true);if($http<200||$http>=300||empty($r['invoice_url'])||empty($r['id'])){error_log('Xendit invoice creation failed HTTP '.$http);exit('Unable to create GCash invoice.');}$pdo->beginTransaction();try{$pdo->prepare("UPDATE orders SET payment_reference=?,payment_invoice_id=?,payment_status='pending' WHERE id=?")->execute([$r['invoice_url'],$r['id'],$id]);$pdo->prepare("UPDATE order_headers SET payment_reference=?,payment_status='pending' WHERE id=?")->execute([$r['invoice_url'],$o['header_id']]);$pdo->commit();}catch(Throwable $e){$pdo->rollBack();throw $e;}redirect($r['invoice_url']);
